const log=m=>{const l=$('#log');l.innerHTML+='<br>'+m;if(l.innerHTML.length>80000){const s=l.innerHTML,i=s.indexOf('<br>',s.length-60000);if(i>0)l.innerHTML=s.slice(i+4)}l.scrollTop=l.scrollHeight};
const delay=l=>window.DLY?DLY(l):0;
const up=l=>{const a=get(l.a),b=get(l.b);return !l.q&&(![a,b].some(n=>n.t=='leo')||Math.hypot(a.x-b.x,a.y-b.y)<=CFG.range)};
function add(t,x,y){const r=vbox();cnt[t]=(cnt[t]||0)+1;
 const n={id:++id,t,name:T[t][1]+' '+cnt[t],ip:(t=='geo'||t=='leo')?'':`10.0.${id}.1`,cidr:24,vlan:1,x:x??r.width*(.1+Math.random()*.6),y:y??r.height*.8};nodes.push(n);if(t=='gs'&&$('#vl'))vlUI();return n}
function tryLink(a,b){if(a==b)return;if(lk(a,b))return log('⚠ A ligação já existe.');
 const A=get(a),B=get(b);
 if((isSat(A)&&!(B.t=='gs'||isSat(B)))||(isSat(B)&&!(A.t=='gs'||isSat(A))))return log('⚠ Satélites só ligam a Estações Terrestres ou a outros satélites (rádio).');
 const c=(isSat(A)||isSat(B))?'radio':(window.wifiOf&&wifiOf(A,B))||$('#cab').value;links.push({a,b,c});if(window.portSync)portSync();log(`🔗 ${A.name} ↔ ${B.name} (${isSat(A)||isSat(B)?'rádio':'cabo '+CAB[c][0]}, ${fmtD(delay({a,b,c}))})`)}
function path(a,b){const q=[[a]],seen=new Set([a]),L=links.filter(up);
 while(q.length){const p=q.shift(),l=p.at(-1);if(l==b)return p;
  L.forEach(k=>{const o=k.a==l?k.b:k.b==l?k.a:null;if(o&&!seen.has(o)){seen.add(o);q.push([...p,o])}})}return null}
function ping(a,b){const A=get(a),B=get(b),RT=route(A,B),p=RT.ok?RT.P:null,R={A:A.name,Ai:A.ip,B:B.name,Bi:B.ip,ida:a,idb:b,res:[],rt:RT};
 if(!p)return explain(Object.assign(R,{k:'noroute'})),log(`❌ ${A.name} → ${B.name}: ${RT.msg}`);
 {const D=fwDeny(p,A,B,'icmp',0,natInfo(p,A,B)||{});if(D)return explain(Object.assign(R,{k:'fw',p,fwd:D})),log(`🛡️ ${D.txt} O Echo Request não chega a ${B.name}.`)}
 {const RB=route(B,A,{reply:1});if(!RB.ok)return explain(Object.assign(R,{k:'noret',p,rb:RB})),log(`⏱ ${A.name} → ${B.name}: o Echo Request chega, mas a resposta não volta. ${RB.msg}`);const D2=fwDeny(RB.P,B,A,'icmp',0,{reply:true});if(D2)return explain(Object.assign(R,{k:'noret',p,rb:{msg:D2.txt}})),log(`⏱ ${A.name} → ${B.name}: a resposta é descartada. ${D2.txt}`)}
 let ow=0;for(let i=0;i<p.length-1;i++)ow+=delay(lk(p[i],p[i+1]));
 log(`📶 Ping a ${B.ip} (${B.name}) de ${A.name} via ${p.map(i=>get(i).name).join(' → ')}`);fwNotes(p,A,B,'icmp',0,natInfo(p,A,B)||{}).forEach(t=>log('&nbsp;&nbsp;🛡️ '+t));{const NI=natInfo(p,A,B);if(NI)log(`&nbsp;&nbsp;🔁 PAT em ${NI.R.name} (${NI.ifn}): ${A.ip} sai como ${NI.patIp}`)}
 let ok=0;for(let i=0;i<CFG.count;i++){if(Math.random()*100<CFG.loss){R.res.push(null);log('&nbsp;&nbsp;⏱ Tempo esgotado.');continue}ok++;const jt=JIT(p),tm=RTT(p)+jt;R.res.push({tm,jt});log(`&nbsp;&nbsp;✅ Resposta de ${B.ip}: tempo=${fmtT(tm)}`)}
 log(`&nbsp;&nbsp;📊 Enviados=${CFG.count}, recebidos=${ok}, perdas=${Math.round(100*(CFG.count-ok)/CFG.count)}%`);
 Object.assign(R,{k:'ok',p,ow});explain(R);const full=[...p,...p.slice(0,-1).reverse()],dur=1800/CFG.speed,t0=performance.now();
 const c=document.createElementNS('http://www.w3.org/2000/svg','circle');c.setAttribute('r',12);c.setAttribute('fill','url(#pkg)');pk.appendChild(c);
 (function f(now){const t=Math.max(0,Math.min((now-t0)/dur,1)),s=t*(full.length-1),i=Math.min(Math.floor(s),full.length-2),u=s-i,n1=get(full[i]),n2=get(full[i+1]);
  if(!n1||!n2){c.remove();return}c.setAttribute('cx',n1.x+(n2.x-n1.x)*u);c.setAttribute('cy',n1.y+(n2.y-n1.y)*u);
  t<1?requestAnimationFrame(f):c.remove()})(t0)}
function focusNode(i){fo=i;const n=get(i);$('#node').innerHTML=n?`<label>Nome<input type="text" id="nn"></label><label>Endereço IP<input type="text" id="ni"></label><label>Prefixo (/CIDR)<input type="number" id="np" min="1" max="32"></label>${isHost(n)?`<label>VLAN<select id="nv">${VL.filter(v=>!v.g||v.g==zoneG(n)).map(v=>`<option value="${v.id}">VLAN ${v.id} · ${v.name}</option>`).join('')}</select></label>`:''}<div id="ipi"></div><div id="rtb"></div><div id="dbd"></div>`:'<small style="opacity:.6">Clica num dispositivo (✋ Mover) para editar nome e IP.</small>';
 if(n){$('#nn').value=n.name;$('#ni').value=n.ip;$('#np').value=n.cidr;$('#nn').oninput=e=>n.name=e.target.value;$('#ni').oninput=e=>{n.ip=e.target.value;ipUI(n)};$('#np').oninput=e=>{const v=+e.target.value;if(v>=1&&v<=32){n.cidr=v;ipUI(n)}};if($('#nv')){$('#nv').value=n.vlan;$('#nv').onchange=e=>n.vlan=+e.target.value}
  ipUI(n);rtUI(n);dataUI(n);if(isStore(n)&&innerWidth<800)$('#panel').classList.remove('h')}}
