const isStore=n=>n&&(n.t=='db'||n.t=='bk'),rn=(a,b,d=0)=>+(a+Math.random()*(b-a)).toFixed(d),fkb=k=>k>=1024?(k/1024).toFixed(1)+' MB':k+' KB';
const TEL=['Telemetria',()=>`Bateria ${rn(78,100)}% · Painéis ${rn(18,46)} °C · TX ${rn(40,95)} W`,()=>rn(2,18)];
const GEN={geo:[['Meteorologia',()=>`Nuvens ${rn(5,95)}% · Vento ${rn(5,80)} km/h · ${rn(-5,36)} °C`,()=>rn(90,700)],['Comunicações',()=>`Feixe ${rn(1,24)} · ${rn(40,900)} Mbps · SNR ${rn(8,18,1)} dB`,()=>rn(30,300)],TEL],
 leo:[['Observação da Terra',()=>`Tile ${'ABCDEFGH'[rn(0,7)]}${rn(1,40)} · ${rn(1,10)} m/px · nuvens ${rn(0,60)}%`,()=>rn(4000,24000)],['Posição GNSS',()=>`Lat ${rn(-60,70,2)}° · Lon ${rn(-180,180,2)}° · Alt ${rn(540,560)} km`,()=>rn(1,6)],TEL]};
const satsOf=(g,any)=>links.map(l=>l.a==g.id?[l,get(l.b)]:l.b==g.id?[l,get(l.a)]:null).filter(x=>x&&x[1]&&isSat(x[1])&&(any||up(x[0]))).map(x=>x[1]);
function recv(z,any,ts){const S=satsOf(z.g,any),srv=z.m.filter(n=>isStore(n)&&(any||path(z.g.id,n.id)));if(!S.length||!srv.length)return;
 const sat=S[Math.random()*S.length|0],G=GEN[sat.t],[tipo,tx,sz]=G[Math.random()*G.length|0],rec={n:z.g.seq=(z.g.seq||0)+1,ts,sat:sat.name,sip:sat.ip,st:z.g.name,tipo,txt:tx(),kb:sz()};
 srv.forEach(n=>{(n.data||(n.data=[])).unshift(rec);if(n.data.length>60)n.data.pop();n.total=(n.total||0)+1;n.kb=(n.kb||0)+rec.kb})}
function dataUI(n){const e=$('#dbd');if(!e||!isStore(n))return;const d=n.data||[],o=e.querySelector('.rows'),y=o?o.scrollTop:0;
 e.innerHTML=`<h3>${n.t=='db'?'Dados recebidos por satélite':'Cópias de segurança'}</h3><small>${d.length?`${n.total} registos · ${fkb(n.kb)} · a mostrar ${d.length}`:'Sem dados. Liga o servidor a uma Estação com ligação a um satélite.'}</small><div class="rows">${d.map(x=>`<div class="rec"><b>${TI[x.tipo]||"📦"} #${x.n} · ${esc(x.tipo)}</b> <small>${new Date(x.ts).toISOString().slice(11,19)} UTC · ${fkb(x.kb)}</small><br>🛰️ ${esc(x.sat)} <small>(${esc(x.sip)})</small> → 📡 ${esc(x.st)}<br><small>${esc(x.txt)}</small></div>`).join('')}</div>`;const r=e.querySelector('.rows');if(r)r.scrollTop=y}
