let KEY='satnet-tracer-v1';
function save(quiet){if(!window.ME)return;try{localStorage.setItem(KEY,JSON.stringify({nodes,links,VL,cnt,id,CFG,CUSTOM,ST,log:$('#log').innerHTML.split('<br>').slice(-150).join('<br>'),t:Date.now()}));const t=new Date().toTimeString().slice(0,8);$('#sv').textContent='guardado às '+t;if(!quiet)log('💾 Progresso guardado às '+t+'.');return true}catch(e){$('#sv').textContent='⚠ não foi possível guardar';if(!quiet)log('⚠ Não foi possível guardar (armazenamento indisponível ou cheio).');return false}}
function load(){try{const d=JSON.parse(localStorage.getItem(KEY));if(!d||!d.nodes||!d.nodes.length)return false;
 nodes=d.nodes;links=d.links||[];cnt=d.cnt||{};id=d.id||0;VL.length=0;VL.push(...d.VL);Object.assign(CFG,d.CFG);Object.assign(CUSTOM,d.CUSTOM||{});Object.assign(ST,d.ST||{});
 document.querySelectorAll('#cfg [data-k],#sec [data-k]').forEach(e=>{const k=e.dataset.k;if(!(k in CFG))return;if(e.type=='checkbox')e.checked=!!CFG[k];else e.value=CFG[k];const b=$('#v_'+k);if(b)b.textContent=CFG[k]});
 document.documentElement.dataset.theme=CFG.theme;st.style.display=CFG.stars?'':'none';
 if(d.log)$('#log').innerHTML=d.log;log('📂 Trabalho restaurado (guardado em '+new Date(d.t).toLocaleString('pt-PT')+').');vlUI();focusNode(null);return true}catch(e){return false}}
$('#svb').onclick=()=>save();setInterval(()=>save(true),4000);addEventListener('pagehide',()=>save(true));document.addEventListener('visibilitychange',()=>{if(document.hidden)save(true)});
stars();if(!load())demo();
